import"./chunk-ZW5NV4UO.js";var a={el:{title:"\u03A0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03B9\u03BA\u03AE \u03BA\u03B1\u03B9 \u03B1\u03BD\u03BF\u03B9\u03BA\u03C4\u03CC \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC \u03C3\u03C4\u03BF Mastodon: \u03C0\u03BF\u03B9\u03BF\u03BD \u03BD\u03B1 \u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03C3\u03B5\u03B9\u03C2",description:"\u03A4\u03AD\u03C3\u03C3\u03B5\u03C1\u03B9\u03C2 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03AF \u03B3\u03B9\u03B1 \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03CC, \u03B1\u03BD\u03BF\u03B9\u03BA\u03C4\u03CC \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC \u03BA\u03B1\u03B9 \u03C4\u03B5\u03C7\u03BD\u03BF\u03BB\u03BF\u03B3\u03AF\u03B1 \u03C3\u03C4\u03B1 \u03B5\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03AC. \u0394\u03B5\u03C2 \u03C4\u03B7 \u03B4\u03B7\u03BC\u03CC\u03C3\u03B9\u03B1 \u03C1\u03BF\u03AE \u03BA\u03B1\u03B9 \u03B4\u03B9\u03AC\u03BB\u03B5\u03BE\u03B5 \u03C0\u03BF\u03B9\u03BF\u03C5\u03C2 \u03B8\u03B1 \u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03C3\u03B5\u03B9\u03C2.",heading:"\u03A0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03B9\u03BA\u03AE \u03BA\u03B1\u03B9 \u03B1\u03BD\u03BF\u03B9\u03BA\u03C4\u03CC \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC \u03C3\u03C4\u03BF Mastodon",listTitle:"\u03A0\u03BB\u03B7\u03C1\u03BF\u03C6\u03BF\u03C1\u03B9\u03BA\u03AE \u03BA\u03B1\u03B9 \u03B1\u03BD\u03BF\u03B9\u03BA\u03C4\u03CC \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC",intro:["\u039C\u03B9\u03B1 \u03BC\u03B9\u03BA\u03C1\u03AE \u03B1\u03C1\u03C7\u03AE \u03B3\u03B9\u03B1 \u03C4\u03B7\u03BD \u03B5\u03BB\u03BB\u03B7\u03BD\u03CC\u03C6\u03C9\u03BD\u03B7 \u03C4\u03B5\u03C7\u03BD\u03BF\u03BB\u03BF\u03B3\u03B9\u03BA\u03AE \u03C3\u03BF\u03C5 \u03C1\u03BF\u03AE: \u03C4\u03AD\u03C3\u03C3\u03B5\u03C1\u03B9\u03C2 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03AF \u03BC\u03B5 \u03B1\u03BD\u03B1\u03C1\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03B3\u03B9\u03B1 \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03CC, \u03B5\u03BB\u03B5\u03CD\u03B8\u03B5\u03C1\u03BF \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC \u03BA\u03B1\u03B9 \u03C8\u03B7\u03C6\u03B9\u03B1\u03BA\u03AC \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03B1. \u039F\u03B9 \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03BF\u03AF \u03B3\u03C1\u03AC\u03C6\u03BF\u03C5\u03BD \u03B5\u03C0\u03AF\u03C3\u03B7\u03C2 \u03C3\u03C4\u03B1 \u03B1\u03B3\u03B3\u03BB\u03B9\u03BA\u03AC \u03BA\u03B1\u03B9 \u03B3\u03B9\u03B1 \u03AC\u03BB\u03BB\u03B1 \u03B8\u03AD\u03BC\u03B1\u03C4\u03B1.","\u0394\u03B5\u03C2 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03B9\u03C2 \u03B4\u03B7\u03BC\u03CC\u03C3\u03B9\u03B5\u03C2 \u03B1\u03BD\u03B1\u03C1\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2. \u03A4\u03B1 \u03B5\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03AC hashtags \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03AD\u03C7\u03BF\u03C5\u03BD \u03BB\u03AF\u03B3\u03B7 \u03AE \u03BA\u03B1\u03B8\u03CC\u03BB\u03BF\u03C5 \u03C0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B7 \u03BA\u03AF\u03BD\u03B7\u03C3\u03B7\xB7 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03C1\u03BF\u03C4\u03AC\u03C3\u03B5\u03B9\u03C2 \u03B3\u03B9\u03B1 \u03C4\u03BF \u03B8\u03AD\u03BC\u03B1, \u03CC\u03C7\u03B9 \u03C5\u03C0\u03CC\u03C3\u03C7\u03B5\u03C3\u03B7 \u03BA\u03B1\u03B8\u03B7\u03BC\u03B5\u03C1\u03B9\u03BD\u03AE\u03C2 \u03C1\u03BF\u03AE\u03C2. \u03A4\u03BF \u03BA\u03BF\u03B9\u03BD\u03CC #FOSS \u03C0\u03B5\u03C1\u03B9\u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03B5\u03B9 \u03C0\u03BF\u03BB\u03CD \u03B1\u03B3\u03B3\u03BB\u03CC\u03C6\u03C9\u03BD\u03BF \u03C0\u03B5\u03C1\u03B9\u03B5\u03C7\u03CC\u03BC\u03B5\u03BD\u03BF."],faq:[{q:"\u03A7\u03C1\u03B5\u03B9\u03AC\u03B6\u03BF\u03BC\u03B1\u03B9 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03CC;",a:"\u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C2 \u03BD\u03B1 \u03B4\u03B5\u03B9\u03C2 \u03C4\u03B1 \u03B4\u03B7\u03BC\u03CC\u03C3\u03B9\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03C0\u03C1\u03BF\u03B5\u03C0\u03B9\u03C3\u03BA\u03CC\u03C0\u03B7\u03C3\u03B7 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03CC. \u03A3\u03C5\u03BD\u03B4\u03AD\u03C3\u03BF\u03C5 \u03BC\u03B5 Mastodon \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03BA\u03B1\u03B9 hashtags \u03AE \u03BD\u03B1 \u03B4\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AE\u03C3\u03B5\u03B9\u03C2 \u03BB\u03AF\u03C3\u03C4\u03B1."},{q:"\u0395\u03AF\u03BD\u03B1\u03B9 \u03CC\u03BB\u03B5\u03C2 \u03BF\u03B9 \u03B1\u03BD\u03B1\u03C1\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C3\u03C4\u03B1 \u03B5\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03AC \u03BA\u03B1\u03B9 \u03BC\u03CC\u03BD\u03BF \u03B3\u03B9\u03B1 \u03C4\u03B5\u03C7\u03BD\u03BF\u03BB\u03BF\u03B3\u03AF\u03B1;",a:"\u038C\u03C7\u03B9. \u0397 \u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B2\u03B1\u03C3\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03C3\u03B5 \u03C4\u03B5\u03C7\u03BD\u03BF\u03BB\u03BF\u03B3\u03B9\u03BA\u03AD\u03C2 \u03B1\u03BD\u03B1\u03C1\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03C3\u03C4\u03B1 \u03B5\u03BB\u03BB\u03B7\u03BD\u03B9\u03BA\u03AC, \u03B1\u03BB\u03BB\u03AC \u03BF\u03B9 \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03AF \u03B3\u03C1\u03AC\u03C6\u03BF\u03C5\u03BD \u03BA\u03B1\u03B9 \u03C3\u03B5 \u03AC\u03BB\u03BB\u03B5\u03C2 \u03B3\u03BB\u03CE\u03C3\u03C3\u03B5\u03C2 \u03BA\u03B1\u03B9 \u03B3\u03B9\u03B1 \u03AC\u03BB\u03BB\u03B1 \u03B8\u03AD\u03BC\u03B1\u03C4\u03B1. \u0394\u03B5\u03C2 \u03C4\u03B7 \u03C1\u03BF\u03AE \u03C0\u03C1\u03B9\u03BD \u03B1\u03BA\u03BF\u03BB\u03BF\u03C5\u03B8\u03AE\u03C3\u03B5\u03B9\u03C2."},{q:"\u03A0\u03CE\u03C2 \u03C0\u03C1\u03BF\u03C4\u03B5\u03AF\u03BD\u03C9 \u03AD\u03BD\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03AE \u03B6\u03B7\u03C4\u03CE \u03B1\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7;",a:"\u0393\u03C1\u03AC\u03C8\u03B5 \u03C3\u03C4\u03BF @mawkingbird@mastodon.social. \u0395\u03BB\u03AD\u03B3\u03C7\u03BF\u03C5\u03BC\u03B5 \u03C4\u03B7 \u03B8\u03B5\u03BC\u03B1\u03C4\u03BF\u03BB\u03BF\u03B3\u03AF\u03B1, \u03C4\u03B7 \u03B3\u03BB\u03CE\u03C3\u03C3\u03B1, \u03C4\u03B7\u03BD \u03C0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B7 \u03B4\u03C1\u03B1\u03C3\u03C4\u03B7\u03C1\u03B9\u03CC\u03C4\u03B7\u03C4\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B1\u03BD\u03B1\u03BA\u03AC\u03BB\u03C5\u03C8\u03B7\u03C2. \u03A3\u03B5\u03B2\u03CC\u03BC\u03B1\u03C3\u03C4\u03B5 \u03C4\u03B1 \u03B1\u03B9\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1 \u03B1\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7\u03C2."}]},hu:{title:"Informatika \xE9s szabad szoftver a Mastodonon: kit \xE9rdemes k\xF6vetni?",description:"H\xE1rom magyarul is \xEDr\xF3 Mastodon-profil programoz\xE1sr\xF3l, szabad szoftverr\u0151l \xE9s technol\xF3gi\xE1r\xF3l. N\xE9zz bele a nyilv\xE1nos bejegyz\xE9sekbe!",heading:"Informatika \xE9s szabad szoftver a Mastodonon",listTitle:"Informatika \xE9s szabad szoftver",intro:["Kis v\xE1logat\xE1s a magyar nyelv\u0171 technol\xF3giai h\xEDrfolyamod elind\xEDt\xE1s\xE1hoz: h\xE1rom profil programoz\xE1sr\xF3l, szabad szoftverr\u0151l \xE9s digit\xE1lis eszk\xF6z\xF6kr\u0151l. A szerz\u0151k angolul \xE9s m\xE1s t\xE9m\xE1kr\xF3l is \xEDrnak.","El\u0151sz\xF6r n\xE9zz bele a nyilv\xE1nos h\xEDrfolyamba. A magyar hashtagek csendesek lehetnek, ak\xE1r friss bejegyz\xE9s n\xE9lk\xFCl: t\xE9mav\xE1laszt\xE1si javaslatok, nem napi aktivit\xE1si \xEDg\xE9retek. A k\xF6z\xF6s #FOSS alatt sok az angol nyelv\u0171 tartalom."],faq:[{q:"Kell hozz\xE1 fi\xF3k?",a:"A nyilv\xE1nos profilokat \xE9s az el\u0151n\xE9zetet fi\xF3k n\xE9lk\xFCl is megn\xE9zheted. A profilok \xE9s hashtagek k\xF6vet\xE9s\xE9hez vagy lista l\xE9trehoz\xE1s\xE1hoz jelentkezz be a Mastodonnal."},{q:"Minden bejegyz\xE9s magyarul \xE9s az informatik\xE1r\xF3l sz\xF3l?",a:"Nem. A v\xE1logat\xE1s magyar nyelv\u0171 technol\xF3giai bejegyz\xE9sekre \xE9p\xFCl, de a szerz\u0151k m\xE1s nyelveken \xE9s m\xE1s t\xE9m\xE1kr\xF3l is \xEDrnak. K\xF6vet\xE9s el\u0151tt n\xE9zz bele a h\xEDrfolyamba."},{q:"Hogyan aj\xE1nlhatok profilt vagy k\xE9rhetem az elt\xE1vol\xEDt\xE1somat?",a:"\xCDrj a @mawkingbird@mastodon.social c\xEDmre. Ellen\u0151rizz\xFCk a t\xE9m\xE1t, a nyelvet, a friss aktivit\xE1st \xE9s a felfedezhet\u0151s\xE9gi be\xE1ll\xEDt\xE1sokat. Az elt\xE1vol\xEDt\xE1si k\xE9r\xE9seket teljes\xEDtj\xFCk."}]},lt:{title:"Technologijos ir atvirasis kodas Mastodon: k\u0105 sekti",description:"Keturi lietuvi\u0161kai ra\u0161antys Mastodon profiliai apie programavim\u0105, atvir\u0105j\u012F kod\u0105 ir technologijas. Per\u017Ei\u016Br\u0117k \u012Fra\u0161us ir pasirink, k\u0105 sekti.",heading:"Technologijos ir atvirasis kodas Mastodon",listTitle:"Technologijos ir atvirasis kodas",intro:["Nedidel\u0117 prad\u017Eia tavo technologij\u0173 srautui lietuvi\u0173 kalba: keturi profiliai apie programavim\u0105, atvir\u0105j\u012F kod\u0105 ir skaitmeninius \u012Frankius. Autoriai taip pat ra\u0161o angli\u0161kai ir kitomis temomis.","Pirmiausia per\u017Ei\u016Br\u0117k vie\u0161us \u012Fra\u0161us. Lietuvi\u0161kos grota\u017Eym\u0117s gali b\u016Bti tylios ar netur\u0117ti nauj\u0173 \u012Fra\u0161\u0173: jos \u017Eymi naudingas temas, o ne \u017Eada kasdien\u012F sraut\u0105. Bendroje #FOSS grota\u017Eym\u0117je daug turinio angl\u0173 kalba."],faq:[{q:"Ar reikia paskyros?",a:"Vie\u0161us profilius ir per\u017Ei\u016Br\u0105 gali skaityti be paskyros. Prisijunk per Mastodon, kad sektum profilius ir grota\u017Eymes arba sukurtum s\u0105ra\u0161\u0105."},{q:"Ar visi \u012Fra\u0161ai lietuvi\u0161ki ir tik apie technologijas?",a:"Ne. Atranka paremta technologij\u0173 \u012Fra\u0161ais lietuvi\u0173 kalba, ta\u010Diau autoriai ra\u0161o ir kitomis kalbomis bei temomis. Prie\u0161 sekdamas per\u017Ei\u016Br\u0117k sraut\u0105."},{q:"Kaip pasi\u016Blyti profil\u012F arba papra\u0161yti pa\u0161alinti sav\u0105j\u012F?",a:"Ra\u0161yk @mawkingbird@mastodon.social. Tikriname tem\u0105, kalb\u0105, naujausi\u0105 veikl\u0105 ir profilio atrandamumo nustatymus. Pa\u0161alinimo pra\u0161ymus vykdome."}]},lv:{title:"Tehnolo\u0123ijas un atv\u0113rtais kods Mastodon: kam sekot",description:"Latviski par programm\u0113\u0161anu, atv\u0113rto kodu un digit\u0101lajiem r\u012Bkiem: septi\u0146i Mastodon profili un t\u0113mturi tavas pl\u016Bsmas s\u0101kumam.",heading:"Tehnolo\u0123ijas un atv\u0113rtais kods Mastodon",listTitle:"Tehnolo\u0123ijas un atv\u0113rtais kods",intro:["Programm\u0113\u0161ana, serveri, digit\u0101lie r\u012Bki un atv\u0113rtais kods \u2014 septi\u0146u profilu izlase las\u012Bt\u0101jiem, kuri v\u0113las par tehnolo\u0123ij\u0101m las\u012Bt latviski. Te ir gan projektu veidot\u0101ji, gan cilv\u0113ki, kuri dal\u0101s ikdienas pieredz\u0113. Da\u013Ca autoru raksta ar\u012B angliski un par cit\u0101m t\u0113m\u0101m.","Vispirms apskati publisko pl\u016Bsmu un izv\u0113lies sev interesanto. Viet\u0113jie t\u0113mturi #Atv\u0113rtaisKods un #Programm\u0113\u0161ana pa\u0161laik ir klusi; tie nenoz\u012Bm\u0113 ikdienas ierakstu pl\u016Bsmu. Kop\u012Bgaj\u0101 #FOSS t\u0113mtur\u012B ir ar\u012B daudz satura angliski."],faq:[{q:"Vai vajadz\u012Bgs konts?",a:"Publiskos profilus un priek\u0161skat\u012Bjumu vari apskat\u012Bt bez konta. Piesl\u0113dzies ar Mastodon, lai sekotu atlas\u012Btajiem profiliem un t\u0113mturiem vai izveidotu sarakstu."},{q:"Vai visi ieraksti b\u016Bs latviski un tikai par tehnolo\u0123ij\u0101m?",a:"N\u0113. Izlase balst\u012Bta uz autoru tehnolo\u0123iju ierakstiem latvie\u0161u valod\u0101, ta\u010Du vi\u0146u pl\u016Bsm\u0101s ir ar\u012B ang\u013Cu valoda un citas t\u0113mas. T\u0113mturu saturs ir publisks un main\u012Bgs."},{q:"K\u0101 pieteikt profilu vai iz\u0146emt savu?",a:"Raksti @mawkingbird@mastodon.social. P\u0101rbaud\u0101m t\u0113mu, valodu, neseno aktivit\u0101ti un profila atra\u0161anas at\u013Caujas. Iz\u0146em\u0161anas l\u016Bgumus iev\u0113rojam."}]}};export{a as COPY};
